## **2. 后端功能扩展**

### **2.1 数据分析模型**
#### **`models.py`**
```python
def get_sales_data(start_date, end_date):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT date(o.timestamp) as order_date, SUM(o.total_amount) as total_sales
        FROM orders o
        WHERE o.timestamp BETWEEN ? AND ?
        GROUP BY order_date
        ORDER BY order_date
    ''', (start_date, end_date))
    sales_data = cursor.fetchall()
    conn.close()
    return [dict(row) for row in sales_data]

def get_inventory_usage():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT i.name, COUNT(o.id) as usage_count
        FROM inventory i
        JOIN orders o ON o.items LIKE '%' || i.name || '%'
        GROUP BY i.id
        ORDER BY usage_count DESC
    ''')
    usage_data = cursor.fetchall()
    conn.close()
    return [dict(row) for row in usage_data]

def get_customer_booking_analysis():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT c.name, COUNT(r.id) as booking_count
        FROM customers c
        JOIN reservations r ON c.id = r.customer_id
        GROUP BY c.id
        ORDER BY booking_count DESC
    ''')
    booking_data = cursor.fetchall()
    conn.close()
    return [dict(row) for row in booking_data]
```

